// this is for all connections made
// 1.neo4j->graph db(store node+relations)
// 2.pinecone->vector db(vectors->similarity)
// 3.gemini-> llm model

// embeddings are generated by pinecone 

import dotenv from "dotenv";
import neo4j from "neo4j-driver"
import { Pinecone } from "@pinecone-database/pinecone";

import { GoogleGenAI } from "@google/genai";

dotenv.config();

// NEO4J setup -> 

const driver=neo4j.driver(
  process.env.NEO4J_URI,
  neo4j.auth.basic(process.env.NEO4J_USERNAME,process.env.NEO4J_PASSWORD)
)
// Pinecone setup->

const pinecone=new Pinecone({apiKey:process.env.PINECONE_API_KEY});
// name of table 
const pineconeIndex=pinecone.index(process.env.PINECONE_INDEX_NAME);

// gemini

const ai = new GoogleGenAI({ apiKey: process.env.GOOGLE_API_KEY });

import { ChatGoogleGenerativeAI } from "@langchain/google-genai";

const llm = new ChatGoogleGenerativeAI({
  model: "gemini-2.5-flash",
  apiKey: process.env.GOOGLE_API_KEY,
  temperature: 0,
  maxOutputTokens: 8192,
  responseMimeType: "application/json",
});




// pinecone embeddings->
// using pinecone model ->1024 dimensions
// this fn embeds one text-> returns 1024-dimension vector
async function embedText(text){
  const response=await pinecone.inference.embed(
    "multilingual-e5-large",
    [text],
    {inputType:"passage",truncate:"END"}
  );
  return response .data[0].values;
}


// embed multiple text->returns array of vec
async function embedTexts(texts) {
  const response=await pinecone.inference.embed(
    "multilingual-e5-large",
    texts,
    {inputType:"passage",truncate:"END"}
  );
  return response.data.map((e)=>e.value);
}


// close all connections 

async function closeConnections(){
  await driver.close()//neo4j closed
  console.log("connections closed");
}

export {driver,pinecone,pineconeIndex,llm,ai,embedText,embedTexts,closeConnections};